# ===================================================================== 89
add(id=89, title="Funding, sponsorship and conflicts of interest: among included studies and in your own review", last_verified=V, prerequisites=["Modules 17, 36, 80"],
 objectives=["Record funding sources and competing interests of included studies and use them as pre-specified moderators.", "Explain why standard risk-of-bias judgements may not capture sponsorship bias.", "Declare and manage your own review's funding and conflicts."],
 why="The Cochrane Handbook (v6, ch. 7) treats conflicts of interest among included studies as a source of bias to consider. Evidence from methodological research suggests sponsorship is associated with more favourable results - and those effects are not fully explained by conventional risk-of-bias items.",
 plain="""**Sponsorship and funding** (industry, foundations, government, institutional) and the **competing interests** of authors can influence design, analysis, reporting and interpretation. In a synthesis you (1) **extract** funding source and declared interests for every included study, (2) treat them as **pre-specified moderators** where plausible (e.g. sponsor vs non-sponsor), and (3) consider them when you **interpret** results. A Cochrane methodology review of industry sponsorship (Lundh et al. 2017; abstract examined via PubMed) reported that, compared with non-industry sponsored studies, industry-sponsored studies more often had favourable efficacy results (RR 1.27, 95% CI 1.17 to 1.37; 25 papers; moderate-quality evidence) and more often favourable conclusions (RR 1.34, 95% CI 1.19 to 1.51; 29 papers; low-quality evidence), and the authors concluded that the association cannot be explained by standard risk-of-bias assessments.""",
 intermediate="""**Interpreting such figures:** that review concerned *drug and device studies in clinical research*; do not transfer the magnitudes to laboratory biology without evidence. The general lesson is methodological: **funding is not a risk-of-bias domain by itself**, but it is a **marker** for potential bias pathways (choice of comparator, selective outcome reporting, spin) that conventional tools can miss. **In laboratory biology** funding sources (company, foundation, grant) and **commercial interests** (patents, start-ups, supplier relationships such as compound manufacturers) are rarely reported systematically - record 'not reported' explicitly instead of guessing. **Analysis:** subgroup or meta-regression by sponsorship, *pre-specified* and interpreted cautiously (few studies, confounding with design quality). **Your own review:** declare funding, the role of funders, personal and financial interests; avoid arrangements that allow funders to alter methods or conclusions; register the protocol (Module 8) to reduce flexibility. **Handling the data:** extracting 'who paid' from acknowledgements and declarations requires care; two extractors reduce errors (Module 17).""",
 advanced="""Distinguish *funding source*, *author financial ties*, *non-financial interests* (intellectual commitments, career incentives) and *institutional conflicts*. Non-financial interests are common in academic research (a reviewer who has built a career on an effect) and should be acknowledged without moralising. For meta-research, treat 'industry vs non-industry' as a crude proxy: funders differ widely. Guidance on disclosing and managing conflicts for *review authors* is part of Cochrane and PRISMA reporting standards (PRISMA 2020 includes items on support and competing interests).""",
 assumptions=["Funding and interests are reported (or explicitly marked as not reported).", "Moderator analyses by sponsorship are exploratory unless pre-specified and adequately powered."],
 formulas=[dict(name="SE of ln RR from a reported 95% CI", tex=r"SE(\ln RR)=\frac{\ln U-\ln L}{2\times1.96}", symbols={"L,U":"95% CI limits of the RR"})],
 worked_example="""Using the abstract's pooled efficacy result (RR 1.27, 95% CI 1.17 to 1.37): SE(ln RR) = (ln 1.37 − ln 1.17)/(2×1.96) = **0.0403**; ln 1.27 = **0.2390**; z = **5.94** (p ≈ 3×10⁻⁹) - the association between sponsorship and favourable efficacy results is statistically clear in that body of evidence. For harms (RR 1.37, 95% CI 0.64 to 2.93; four papers): SE(ln RR) = **0.388**, z = **0.81**, p = **0.42**: imprecise, consistent with both no association and a strong one, and graded very low-quality evidence by the authors. Effect sizes from these meta-research studies describe *associations between sponsorship and reported results* - not the size of bias in any specific trial.""",
 examples=[("Preclinical","Compound supplied by a company that also funds the study."),("Clinical","Industry-sponsored drug trial."),("Ecology","Funder with a stake in the management outcome."),("Genetics","Biotech-funded variant study."),("Education","Publisher-funded curriculum evaluation.")],
 mistakes=["Ignoring funding information.", "Using 'industry funded' as a proxy for 'biased'.", "Post-hoc sponsorship subgroups reported as findings.", "Not declaring your own funding."],
 misconceptions=[("'Risk-of-bias tools capture sponsorship effects.'","The cited review found an association not explained by standard risk-of-bias assessments."),("'Public funding guarantees neutrality.'","Non-financial interests and publication incentives still operate.")],
 controversies=["Whether to exclude sponsored studies.", "Measuring non-financial conflicts."],
 decision_tree=[("Funding reported?","Extract; else mark 'not reported'."),("Enough studies per group?","Pre-specified subgroup/meta-regression."),("Own conflicts?","Declare in the protocol and manuscript.")],
 exercises=["Extract funding and competing-interest statements for five studies in your area.", "Draft the funding/competing-interest paragraph for your review.", "List non-financial interests relevant to your topic."],
 integrity="Declare your own funding and interests; never allow funders to alter methods or conclusions.", further=["lundh2017","page2021","cumpston2019"],
 coding=dict(r='lo <- 1.17; hi <- 1.37; rr <- 1.27\nse <- (log(hi) - log(lo)) / (2 * qnorm(0.975)); c(log(rr), se, log(rr) / se)   # 0.2390 0.0403 5.94', python='import math\nse=(math.log(1.37)-math.log(1.17))/(2*1.959964); print(math.log(1.27), se, math.log(1.27)/se)'),
 application="**Milestone 7/9:** add funding and competing interests to the extraction form; decide on a pre-specified sponsorship moderator.", checklist=["Funding extracted","Interests extracted","Moderator pre-specified","Own conflicts declared"],
 quiz=[dict(q="SE of ln RR for RR 1.27 (95% CI 1.17–1.37):", opts=["0.0403","0.2390","0.5","0.1"], ans=0, why="(ln1.37−ln1.17)/(2×1.96).", numeric=True),
  dict(q="z for the efficacy association (ln1.27/SE):", opts=["5.94","1.96","0.81","1.27"], ans=0, why="0.2390/0.0403.", numeric=True),
  dict(q="Is funding itself a risk-of-bias domain?", opts=["No - it is a marker for possible bias pathways","Yes, always","Only for industry","Never relevant"], ans=0, why="Lundh 2017: not explained by standard RoB items."),
  dict(q="If funding is not reported, record...", opts=["'Not reported'","A guess","Industry","Public"], ans=0, why="No guessing."),
  dict(q="Post-hoc sponsorship subgroup analyses are...", opts=["Exploratory","Confirmatory","Required","Proof of bias"], ans=0, why="Pre-specify to confirm.")])

# ===================================================================== 90
add(id=90, title="Complex interventions, context and equity: applicability beyond the average effect", last_verified=V, prerequisites=["Modules 17, 35, 56, 57"],
 objectives=["Recognise when an intervention is complex and what that means for synthesis.", "Plan equity-relevant extraction (who was studied, who benefits) and absolute-effect reporting.", "Use PRISMA-Equity and complex-intervention frameworks to structure the review."],
 why="An average pooled effect can hide who benefits and where it works. The Cochrane Handbook (v6) has chapters on equity and specific populations (ch. 16) and intervention complexity (ch. 17): ignoring them yields conclusions that do not apply to the settings and groups that matter.",
 plain="""**Complex interventions** have several interacting components, depend on context and delivery (staff, setting, dose, adherence) and may act through multiple mechanisms (Skivington et al. 2021 update the Medical Research Council framework; Pfadenhauer et al. 2017 propose the CICI framework for context and implementation). In laboratory biology the analogue is an intervention whose effect depends on **husbandry, genetic background, diet, temperature, supplier, age at start and dose schedule**: 'the same compound' is not the same experiment. **Equity** asks whether effects and burdens differ across social or biological strata (sex, age, ancestry, socioeconomic status in human studies; strain/sex in animal work). PRISMA-Equity 2012 (Welch et al. 2012) extends PRISMA reporting for equity-focused reviews.""",
 intermediate="""**Practical steps:** (1) list **effect modifiers** in the protocol and extract them (sex, age, strain, dose, setting, delivery, follow-up); (2) **map components** of complex interventions and analyse by component only if enough studies exist (component NMA/meta-regression, Module 42/36); (3) report **absolute effects at stated baselines**: a constant relative effect produces different absolute benefits where baseline risk differs - important for equity; (4) describe the **applicability** of the evidence (populations studied vs target populations); (5) avoid *ecological* interpretation of subgroup differences; (6) integrate qualitative evidence on context and implementation (Module 54) and realist approaches (Module 56). **Reporting** uses PRISMA 2020 with the equity/complexity extensions as appropriate.""",
 advanced="""Subgroup/effect-modification analyses based on *study-level* proportions (e.g. proportion female) are ecological and cannot establish individual-level modification; IPD (Module 46) or within-study contrasts are required. For complex interventions, heterogeneity is expected and informative; a single pooled effect may be unhelpful, and prediction intervals plus explanatory moderators are more useful. Many animal studies use one sex or one strain, so evidence for 'who benefits' may simply be absent: record the absence explicitly.""",
 assumptions=["Effect modifiers are pre-specified and measured comparably.", "Absolute effects use plausible baseline risks for the target groups."],
 formulas=[dict(name="Absolute risk reduction at different baselines", tex=r"ARR_g=p_{c,g}\,(1-RR),\qquad NNT_g=\frac1{ARR_g}", symbols={"g":"subgroup/setting","p_{c,g}":"baseline risk in subgroup g","RR":"common relative effect"})],
 worked_example="""Suppose the pooled relative effect is RR = 0.80 in both settings but baseline risk is 10% in group A and 30% in group B. Absolute risk reduction: A = 0.10×0.20 = **0.02** (NNT **50**); B = 0.30×0.20 = **0.06** (NNT **16.7**). The *same relative effect* delivers three times the absolute benefit in group B: a policy that reports only the RR hides this; an equity-focused summary reports both. (This assumes a constant relative effect, which is itself an assumption to examine.)""",
 examples=[("Preclinical","Effect depends on strain and sex."),("Clinical","Complex behavioural interventions."),("Ecology","Management effects across habitats."),("Genetics","Ancestry-specific allele effects."),("Education","Programmes in advantaged vs disadvantaged schools.")],
 mistakes=["Reporting only relative effects.", "Interpreting study-level proportions as individual-level modification.", "Ignoring implementation context.", "Treating 'not studied' as 'no effect'."],
 misconceptions=[("'The pooled effect applies equally to everyone.'","Relative and absolute effects can differ across groups."),("'No subgroup difference means equity is not an issue.'","Power for subgroup tests is usually low.")],
 controversies=["Component analysis in complex interventions.", "Measuring equity in laboratory-animal research."],
 decision_tree=[("Multi-component intervention?","Map components; consider component analysis or narrative synthesis."),("Equity question?","Extract PROGRESS-type factors/strata and report absolute effects."),("Subgroup claim?","Within-study contrasts or IPD.")],
 exercises=["List five effect modifiers for your topic.", "Compute ARR and NNT for baselines 5%, 15%, 40% at RR 0.75.", "Write an applicability statement for your review."],
 integrity="State who and what was studied and where the evidence is silent; do not generalise beyond the evidence.", further=["welch2012","skivington2021","pfadenhauer2017","sterne2019rob2"],
 coding=dict(r='rr <- 0.80; p <- c(A = 0.10, B = 0.30)\narr <- p * (1 - rr); rbind(ARR = arr, NNT = round(1 / arr, 1))   # A 0.02 50; B 0.06 16.7', python='rr=0.80\nfor g,p in (("A",0.10),("B",0.30)): arr=p*(1-rr); print(g, round(arr,3), round(1/arr,1))'),
 application="**Milestone 3/7:** list effect modifiers and strata in the protocol and add them to the extraction form.", checklist=["Effect modifiers listed","Strata extracted","Absolute effects at baselines","Applicability statement"],
 quiz=[dict(q="ARR in group B (baseline 30%, RR 0.80):", opts=["0.06","0.02","0.20","0.30"], ans=0, why="0.30×0.20.", numeric=True),
  dict(q="NNT in group A (baseline 10%, RR 0.80):", opts=["50","16.7","10","5"], ans=0, why="1/0.02.", numeric=True),
  dict(q="Study-level subgroup patterns are...", opts=["Ecological and cannot prove individual-level modification","Individual-level","Always valid","Causal"], ans=0, why="Ecological fallacy."),
  dict(q="A complex intervention typically has...", opts=["Interacting components and context dependence","One component","No mechanism","Fixed effects only"], ans=0, why="Skivington 2021."),
  dict(q="'Not studied' means...", opts=["Evidence is absent, not evidence of no effect","No effect","Zero effect","Negative effect"], ans=0, why="Absence of evidence.")])
